                v.set(rate, gain * 0.5);
            } else if let Some((pcm, table_vol)) = crate::sfx::class_sample(&class) {
                s.voices.insert(class, crate::playback::play_loop(pcm, rate, gain * table_vol * 0.5));
            }
        }
    }
